function validate([s, k]) {
  if (s.length < 1 || s.length > 10000) return 's needs 1 to 10^4 letters.';
  if (!/^[a-z]+$/.test(s)) return 's uses only lowercase English letters.';
  for (let i = 0, j = s.length - 1; i < j; i++, j--) {
    if (s[i] !== s[j]) return 's must be a palindrome.';
  }
  if (k < 1 || k > 1000000) return 'k is between 1 and 10^6.';
  return null;
}

