function smallestPalindrome(s, k) {
  const counts = new Array(26).fill(0);
  for (const ch of s) {
    counts[ch.charCodeAt(0) - 97]++;
  }
  let middle = '';
  for (let letter = 0; letter < 26; letter++) {
    if (counts[letter] % 2 === 1) {
      middle = String.fromCharCode(97 + letter);
    }
    counts[letter] = Math.floor(counts[letter] / 2);
  }
  const half = Math.floor(s.length / 2);
  const choose = (slots, count) => {
    const smaller = Math.min(count, slots - count);
    let ways = 1;
    for (let i = 1; i <= smaller && ways < k; i++) {
      ways = (ways * (slots - smaller + i)) / i;
    }
    return Math.min(ways, k);
  };
  const arrangements = (slots) => {
    let total = 1;
    for (let letter = 0; letter < 26 && total < k; letter++) {
      total = Math.min(k, total * choose(slots, counts[letter]));
      slots -= counts[letter];
    }
    return total;
  };
  if (arrangements(half) < k) {
    return '';
  }
  let left = '';
  for (let position = 0; position < half; position++) {
    for (let letter = 0; letter < 26; letter++) {
      if (counts[letter] === 0) {
        continue;
      }
      counts[letter]--;
      const ways = arrangements(half - position - 1);
      if (ways >= k) {
        left += String.fromCharCode(97 + letter);
        break;
      }
      k -= ways;
      counts[letter]++;
    }
  }
  return left + middle + [...left].reverse().join('');
}

