function smallestPalindrome(s, k) {
  // A palindrome is its first half, the middle letter and the mirror. Sort the first half of s and step
  // through its distinct orderings in lexicographic order with next-permutation, k - 1 times.
  const half = [...s.slice(0, Math.floor(s.length / 2))].sort();
  const middle = s.length % 2 === 1 ? s[Math.floor(s.length / 2)] : '';
  for (let step = 1; step < k; step++) {
    let i = half.length - 2;
    while (i >= 0 && half[i] >= half[i + 1]) i--;
    if (i < 0) return '';
    let j = half.length - 1;
    while (half[j] <= half[i]) j--;
    let swap = half[i];
    half[i] = half[j];
    half[j] = swap;
    for (let a = i + 1, b = half.length - 1; a < b; a++, b--) {
      swap = half[a];
      half[a] = half[b];
      half[b] = swap;
    }
  }
  const first = half.join('');
  return first + middle + [...first].reverse().join('');
}

