function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const random = (alphabet) => alphabet[pick(0, alphabet.length - 1)];
  let alphabet;
  let halfText;
  let k;
  if (size !== 'large') {
    alphabet = letters.slice(0, pick(1, 3));
    halfText = Array.from({ length: pick(0, 5) }, () => random(alphabet)).join('');
    k = rand() < 0.5 ? pick(1, 4) : pick(1, 60);
  } else {
    const length = pick(4000, 4999);
    const mode = pick(0, 2);
    if (mode === 0) {
      // Several letter kinds: far more than 10^6 palindromes exist.
      alphabet = letters.slice(0, pick(2, 26));
      halfText = Array.from({ length }, () => random(alphabet)).join('');
    } else if (mode === 1) {
      // One common letter and one to three rare ones: the count may fall short of k.
      alphabet = letters;
      const common = random(letters);
      const rare = pick(1, 3);
      halfText = Array.from({ length }, (_, i) => (i < rare ? random(letters) : common)).join('');
    } else {
      // A single letter kind (apart from the middle): exactly one palindrome.
      alphabet = letters;
      halfText = random(letters).repeat(length);
    }
    k = rand() < 0.3 ? 1000000 : pick(1, 1000000);
  }
  const middle = halfText.length === 0 || rand() < 0.5 ? random(alphabet) : '';
  return [halfText + middle + [...halfText].reverse().join(''), k];
}
